#include <stdarg.h>
#include "../common/retro-games/puzzles/vendor/slant.c"
void fatal(const char *format,...){va_list a;va_start(a,format);vfprintf(stderr,format,a);va_end(a);fputc('\n',stderr);exit(2);}
void frontend_default_colour(frontend *f,float *out){(void)f;out[0]=out[1]=out[2]=0.9F;}
static game_params *params;
static game_state *from_id(const char *id){char *copy=dupstr(id),*p=strchr(copy,':');if(!p)fatal("Missing ID");*p++=0;params=default_params();decode_params(params,copy);const char *e=validate_params(params,true);if(!e)e=validate_desc(params,p);if(e)fatal("Original validation: %s",e);game_state *s=new_game(NULL,params,p);sfree(copy);return s;}
static game_state *step(game_state *s,const char *m){game_state *n=execute_move(s,m);if(!n)fatal("Original rejection: %s",m);free_game(s);return n;}
static unsigned colour565(float *p,int c){unsigned r=(unsigned)(p[3*c]*255+.5F),g=(unsigned)(p[3*c+1]*255+.5F),b=(unsigned)(p[3*c+2]*255+.5F);return ((r>>3)<<11)|((g>>2)<<5)|(b>>3);}
static void output(game_state *s){int n;float *p=game_colours(NULL,&n);printf("{\"w\":%d,\"h\":%d,\"status\":%d,\"cheated\":%d,\"palette\":[%u,%u,%u,%u],\"cells\":[",s->p.w,s->p.h,game_status(s),s->used_solve,colour565(p,COL_BACKGROUND),colour565(p,COL_INK),colour565(p,COL_GROUNDED),colour565(p,COL_ERROR));for(int i=0;i<s->p.w*s->p.h;i++)printf("%s%d",i?",":"",s->soln[i]);printf("],\"errors\":[");for(int i=0;i<(s->p.w+1)*(s->p.h+1);i++)printf("%s%u",i?",":"",s->errors[i]);printf("],\"clues\":[");for(int i=0;i<(s->p.w+1)*(s->p.h+1);i++)printf("%s%d",i?",":"",s->clues->clues[i]);puts("]}");sfree(p);}
static void self_test(void){game_state *s=from_id("2x2:i");assert(!game_status(s));game_ui *ui=new_ui(s);game_drawstate *ds=game_new_drawstate(NULL,s);game_set_size(NULL,ds,params,24);
 char *m=interpret_move(s,ui,ds,36,36,LEFT_BUTTON);assert(!strcmp(m,"\\0,0"));s=step(s,m);sfree(m);m=interpret_move(s,ui,ds,36,36,LEFT_BUTTON);assert(!strcmp(m,"/0,0"));s=step(s,m);sfree(m);m=interpret_move(s,ui,ds,36,36,LEFT_BUTTON);assert(!strcmp(m,"C0,0"));s=step(s,m);sfree(m);m=interpret_move(s,ui,ds,36,36,RIGHT_BUTTON);assert(!strcmp(m,"/0,0"));sfree(m);
 assert(execute_move(s,"/2,0")==NULL&&execute_move(s,"/0,-1")==NULL&&execute_move(s,"invalid")==NULL);game_free_drawstate(NULL,ds);free_ui(ui);
 s=step(s,"/0,0;\\1,0;\\0,1;/1,1");assert(!game_status(s));int errors=0;for(int i=0;i<9;i++)errors|=s->errors[i];assert(errors&ERR_SQUARE);free_game(s);free_params(params);
 s=from_id("2x2:0h");s=step(s,"\\0,0;\\1,0;\\0,1;\\1,1");assert(!game_status(s)&&s->errors[0]&ERR_VERTEX);free_game(s);free_params(params);
 s=from_id("2x2:0h");s=step(s,"/0,0;/1,0;/0,1;/1,1");assert(game_status(s)==1&&!s->used_solve);free_game(s);free_params(params);
 puts("PASS: original Left/Right diagonal cycles, blank reset, invalid bounds/syntax, closed-loop error, numbered-vertex error, full non-loop uncheated victory");}
int main(int argc,char **argv){if(argc==2&&!strcmp(argv[1],"--self-test")){self_test();return 0;}if(argc>=7&&!strcmp(argv[1],"--input")){game_state *s=from_id(argv[2]);for(int i=7;i<argc;i++)s=step(s,argv[i]);game_ui *ui=new_ui(s);game_drawstate *ds=game_new_drawstate(NULL,s);game_set_size(NULL,ds,params,atoi(argv[3]));char *m=interpret_move(s,ui,ds,atoi(argv[4]),atoi(argv[5]),!strcmp(argv[6],"R")?RIGHT_BUTTON:LEFT_BUTTON);if(!m||m==MOVE_UI_UPDATE||m==MOVE_NO_EFFECT||m==MOVE_UNUSED)fatal("Original input has no move");puts(m);sfree(m);game_free_drawstate(NULL,ds);free_ui(ui);free_game(s);free_params(params);return 0;}if(argc<2)fatal("Usage: native-oracle ID [moves]");game_state *s=from_id(argv[1]);for(int i=2;i<argc;i++)s=step(s,argv[i]);output(s);free_game(s);free_params(params);return 0;}
